.stats-panel {
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 0.75rem;
  padding: 0.75rem;
  margin-bottom: 1rem;
}
.stats-panel h4 {
  margin: 0 0 0.6rem;
  font-size: 0.8rem;
  color: #334155;
  text-align: center;
}
.stats-table {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}
.stat-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.35rem 0.5rem;
  background: #f8fafc;
  border-radius: 0.4rem;
  font-size: 0.72rem;
}
.stat-label {
  color: #64748b;
}
.stat-value {
  font-weight: 700;
  color: #334155;
  font-family: monospace;
}
.stat-value.hot { color: #ef4444; }
.stat-value.acid { color: #ef4444; }
.stat-value.base { color: #8b5cf6; }
.stat-value.neutral { color: #22c55e; }
.stat-value.heating { color: #f59e0b; }
.stats-empty {
  text-align: center;
  font-size: 0.7rem;
  color: #94a3b8;
  padding: 1rem 0;
}

